window.RMY_WHO = Object.assign({
  "rajaraja": { "av": "🐅", "en": "Rājarāja Cōḷa I", "te": "మొదటి రాజరాజ చోళుడు", "d": "Cōḷa king of Thanjavur (985–about 1014 CE), born Arumoḻivarman, son of Sundara Cōḷa. He conquered the far south, northern Laṅkā and the Maldives, allied with the Eastern Cālukyas of Veṅgī, and built the Rājarājeśvaram (Bṛhadīśvara) temple at Thanjavur.", "dt": "తంజావూరు చోళ రాజు (క్రీ.శ. 985–సుమారు 1014), పుట్టు పేరు అరుమొళివర్మ, సుందర చోళుని కుమారుడు. దక్షిణాది అంతటినీ, ఉత్తర లంకనూ, మాల్దీవులనూ జయించాడు; వేంగీ తూర్పు చాళుక్యులతో బంధుత్వం కలుపుకున్నాడు; తంజావూరులో రాజరాజేశ్వరం (బృహదీశ్వర) ఆలయం కట్టించాడు." },
  "vijayalaya": { "av": "🐅", "en": "Vijayālaya", "te": "విజయాలయుడు", "d": "Founder of the later Cōḷa line, who took Thanjavur in about 850 CE. Later Cōḷa copper plates begin the family's rise with him.", "dt": "తరువాతి చోళ వంశ స్థాపకుడు; సుమారు క్రీ.శ. 850లో తంజావూరును పట్టుకున్నాడు. తరువాతి చోళ రాగి శాసనాలు వంశపు ఎదుగుదలను అతనితోనే మొదలుపెడతాయి." },
  "parantaka1": { "av": "⚔️", "en": "Parāntaka I", "te": "మొదటి పరాంతకుడు", "d": "Cōḷa king (about 907–955 CE), great-grandfather of Rājarāja. He conquered Madurai, but his army was beaten by the Rāṣṭrakūṭa Kṛṣṇa III at Takkōlam in about 949 CE. The famous Uttaramērūr inscriptions on village assemblies date from his reign.", "dt": "చోళ రాజు (సుమారు క్రీ.శ. 907–955), రాజరాజుకు ముత్తాత. మదురైని జయించాడు; కానీ సుమారు క్రీ.శ. 949లో తక్కోలం దగ్గర రాష్ట్రకూట మూడవ కృష్ణుని చేతిలో అతని సైన్యం ఓడిపోయింది. గ్రామ సభల గురించిన ప్రసిద్ధ ఉత్తరమేరూరు శాసనాలు అతని కాలానివే." },
  "sundarachola": { "av": "👑", "en": "Sundara Cōḷa (Parāntaka II)", "te": "సుందర చోళుడు (రెండవ పరాంతకుడు)", "d": "Cōḷa king (about 957–970 CE), father of Āditya II, Kundavai and Rājarāja I. He won back much of the south from the Pāṇḍyas. His Anbil copper plates give the family's genealogy.", "dt": "చోళ రాజు (సుమారు క్రీ.శ. 957–970), రెండవ ఆదిత్యుడు, కుందవై, మొదటి రాజరాజుల తండ్రి. పాండ్యుల నుండి దక్షిణాదిలో చాలా భాగాన్ని తిరిగి గెలుచుకున్నాడు. అతని అన్బిల్ రాగి శాసనాలు వంశావళిని చెబుతాయి." },
  "adityakarikala": { "av": "🗡️", "en": "Āditya II Karikāla", "te": "రెండవ ఆదిత్య కరికాలుడు", "d": "Elder brother of Rājarāja I and crown prince of Sundara Cōḷa. His inscriptions boast that he killed the Pāṇḍya Vīrapāṇḍya. He was murdered in about 969 CE; an inscription of Rājarāja's second year punishes those who killed him.", "dt": "మొదటి రాజరాజు అన్నగారు, సుందర చోళుని యువరాజు. పాండ్య వీరపాండ్యుని చంపానని అతని శాసనాలు గొప్పగా చెబుతాయి. సుమారు క్రీ.శ. 969లో హత్యకు గురయ్యాడు; అతన్ని చంపినవారిని శిక్షించిన శాసనం రాజరాజు రెండవ పాలనా సంవత్సరానిది." },
  "kundavai": { "av": "🪔", "en": "Kundavai", "te": "కుందవై", "d": "Elder sister of Rājarāja I, daughter of Sundara Cōḷa, and wife of the chief Vallavaraiyan Vandiyadevan. The Thanjavur inscriptions list her many gifts to the great temple; Rājarāja had them engraved beside his own.", "dt": "మొదటి రాజరాజు అక్కగారు, సుందర చోళుని కుమార్తె, సామంతుడు వల్లవరైయన్ వందియదేవన్ భార్య. తంజావూరు మహాలయానికి ఆమె ఇచ్చిన ఎన్నో కానుకలను తంజావూరు శాసనాలు చెబుతాయి; రాజరాజు వాటిని తన కానుకలతో పాటే రాతిపై చెక్కించాడు." },
  "uttamachola": { "av": "🛕", "en": "Uttama Cōḷa (Madhurāntaka)", "te": "ఉత్తమ చోళుడు (మధురాంతకుడు)", "d": "Cōḷa king (about 970–985 CE), cousin of Sundara Cōḷa and son of Gaṇḍarāditya and Sembiyan Mahādevī. The Tiruvālaṅgāḍu plates say Arumoḻi let him rule first and was made his heir.", "dt": "చోళ రాజు (సుమారు క్రీ.శ. 970–985), సుందర చోళుని దాయాది, గండరాదిత్యుడు, సెంబియన్ మహాదేవిల కుమారుడు. అరుమొళి అతనికే ముందు పాలన వదిలాడనీ, అతను అరుమొళిని తన వారసునిగా చేశాడనీ తిరువాలంగాడు శాసనాలు చెబుతాయి." },
  "sembiyanmahadevi": { "av": "🪷", "en": "Sembiyan Mahādevī", "te": "సెంబియన్ మహాదేవి", "d": "Cōḷa queen, widow of Gaṇḍarāditya and mother of Uttama Cōḷa. For decades she had old brick temples rebuilt in stone and gave fine bronze images; her gifts are known from many inscriptions.", "dt": "చోళ రాణి, గండరాదిత్యుని భార్య, ఉత్తమ చోళుని తల్లి. దశాబ్దాల పాటు పాత ఇటుక గుడులను రాతితో మళ్ళీ కట్టించి, అందమైన కంచు విగ్రహాలు సమర్పించింది; ఎన్నో శాసనాల వల్ల ఆమె దానాలు తెలుస్తాయి." },
  "rajendra": { "av": "🌊", "en": "Rājendra Cōḷa I", "te": "మొదటి రాజేంద్ర చోళుడు", "d": "Son of Rājarāja I and Cōḷa king (about 1012/1014–1044 CE). As a prince he led his father's armies against the Cālukyas; as king he marched to the Gaṅgā, founded Gaṅgaikoṇḍacōḷapuram and sent a fleet against Śrīvijaya.", "dt": "మొదటి రాజరాజు కుమారుడు, చోళ రాజు (సుమారు క్రీ.శ. 1012/1014–1044). రాకుమారుడుగా తండ్రి సైన్యాలను చాళుక్యులపైకి నడిపాడు; రాజయ్యాక గంగ వరకు దండెత్తి, గంగైకొండచోళపురం కట్టి, శ్రీవిజయంపైకి నౌకాదళం పంపాడు." },
  "mahinda5": { "av": "🏯", "en": "Mahinda V", "te": "ఐదవ మహింద", "d": "King of Laṅkā at Anurādhapura in the late tenth and early eleventh century. The Cūḷavaṃsa says his kingdom fell into disorder, that the Cōḷas took the north, and that he was later carried off to the Cōḷa land (in Rājendra I's time). Not the same person as Aśoka's son Mahinda.", "dt": "పదవ శతాబ్దం చివర, పదకొండవ శతాబ్దం మొదట్లో అనురాధపురంలో లంక రాజు. అతని రాజ్యం అల్లకల్లోలమైందనీ, చోళులు ఉత్తర భాగాన్ని పట్టుకున్నారనీ, తరువాత (మొదటి రాజేంద్రుని కాలంలో) అతన్ని చోళ దేశానికి తీసుకువెళ్ళారనీ చూళవంశం చెబుతుంది. అశోకుని కుమారుడు మహిందుడు కాదు." },
  "shaktivarman1": { "av": "🏞️", "en": "Śaktivarman I", "te": "మొదటి శక్తివర్మ", "d": "Eastern Cālukya king of Veṅgī (about 999–1011 CE), son of Dānārṇava. After years of exile he regained the Veṅgī throne with Cōḷa help.", "dt": "వేంగీ తూర్పు చాళుక్య రాజు (సుమారు క్రీ.శ. 999–1011), దానార్ణవుని కుమారుడు. ఏళ్ళ తరబడి ప్రవాసం తర్వాత చోళుల సహాయంతో వేంగీ సింహాసనాన్ని తిరిగి పొందాడు." },
  "vimaladitya": { "av": "💍", "en": "Vimalāditya", "te": "విమలాదిత్యుడు", "d": "Eastern Cālukya king of Veṅgī (about 1011–1018 CE), younger brother of Śaktivarman I. He married Kundavai, daughter of Rājarāja I; their son was Rājarāja Narendra.", "dt": "వేంగీ తూర్పు చాళుక్య రాజు (సుమారు క్రీ.శ. 1011–1018), మొదటి శక్తివర్మ తమ్ముడు. మొదటి రాజరాజు కుమార్తె కుందవైని పెళ్ళి చేసుకున్నాడు; వారి కుమారుడే రాజరాజ నరేంద్రుడు." },
  "rajarajanarendra": { "av": "📖", "en": "Rājarāja Narendra", "te": "రాజరాజ నరేంద్రుడు", "d": "Eastern Cālukya king of Veṅgī (about 1019–1061 CE), grandson of Rājarāja Cōḷa I through his mother and son-in-law of Rājendra I. Nannaya began the Telugu Mahābhārata at his court; Rājamahendravaram (Rajahmundry) is linked with him by tradition.", "dt": "వేంగీ తూర్పు చాళుక్య రాజు (సుమారు క్రీ.శ. 1019–1061), తల్లి వైపు నుండి మొదటి రాజరాజ చోళుని మనుమడు, మొదటి రాజేంద్రుని అల్లుడు. అతని ఆస్థానంలోనే నన్నయ ఆంధ్ర మహాభారతం మొదలుపెట్టాడు; రాజమహేంద్రవరం (రాజమండ్రి) అతనితో ముడిపడి ఉందని సంప్రదాయం." },
  "nannaya": { "av": "🪶", "en": "Nannaya", "te": "నన్నయ", "d": "Telugu poet of the eleventh century, called the Ādikavi of Telugu. At the court of Rājarāja Narendra of Veṅgī he began the Āndhra Mahābhāratamu, which Tikkana and Errana later completed.", "dt": "పదకొండవ శతాబ్దపు తెలుగు కవి, ఆదికవి అని పిలుస్తారు. వేంగీ రాజరాజ నరేంద్రుని ఆస్థానంలో ఆంధ్ర మహాభారతం మొదలుపెట్టాడు; తరువాత తిక్కన, ఎర్రన దాన్ని పూర్తి చేశారు." },
  "kulottunga1": { "av": "🐅", "en": "Kulottuṅga I", "te": "మొదటి కులోత్తుంగుడు", "d": "Son of Rājarāja Narendra of Veṅgī and the Cōḷa princess Ammaṅgadevī. In 1070 CE he became Cōḷa king, joining the Cōḷa and Eastern Cālukya lines; he ruled until about 1122.", "dt": "వేంగీ రాజరాజ నరేంద్రుడు, చోళ రాకుమారి అమ్మంగదేవిల కుమారుడు. క్రీ.శ. 1070లో చోళ రాజయ్యాడు; చోళ, తూర్పు చాళుక్య వంశాలు అతనిలో కలిశాయి. సుమారు 1122 వరకు పాలించాడు." },
  "satyashraya": { "av": "🐗", "en": "Satyāśraya", "te": "సత్యాశ్రయుడు", "d": "Western Cālukya king of Kalyāṇi (about 997–1008 CE), son of Tailapa II. He fought Rājarāja I; his Hoṭṭūr inscription tells the Cālukya side of the war.", "dt": "కళ్యాణి పశ్చిమ చాళుక్య రాజు (సుమారు క్రీ.శ. 997–1008), రెండవ తైలపుని కుమారుడు. మొదటి రాజరాజుతో పోరాడాడు; అతని హొట్టూరు శాసనం యుద్ధంలో చాళుక్యుల పక్షం కథను చెబుతుంది." },
  "kunjaramallan": { "av": "📐", "en": "Kuñcaramallan Rājarāja Peruntaccan", "te": "కుంజరమల్లన్ రాజరాజ పెరుంతచ్చన్", "d": "Master builder of the Thanjavur temple, named in its inscriptions with the title Peruntaccan, “great carpenter” (chief architect).", "dt": "తంజావూరు ఆలయ ప్రధాన శిల్పి; ఆలయ శాసనాలు అతన్ని పెరుంతచ్చన్ — “గొప్ప వడ్రంగి” (ప్రధాన వాస్తుశిల్పి) — అనే బిరుదుతో పేర్కొంటాయి." },
  "karuvurdevar": { "av": "🙏", "en": "Karuvūr Dēvar", "te": "కరువూర్ దేవర్", "d": "Tamil Śaiva poet whose hymns, including one on the Rājarājeśvaram temple, are in the ninth Tirumuṟai (Tiruvicaippā). Tradition calls him Rājarāja's guru; he has a shrine in the Thanjavur temple.", "dt": "తమిళ శైవ కవి; రాజరాజేశ్వరం ఆలయంపై ఒకటి సహా అతని పదికాలు తొమ్మిదవ తిరుమురై (తిరువిసైప్పా)లో ఉన్నాయి. అతను రాజరాజు గురువని సంప్రదాయం; తంజావూరు ఆలయంలో అతనికి ఒక సన్నిధి ఉంది." },
  "nambiandarnambi": { "av": "📜", "en": "Nambi Āṇḍār Nambi", "te": "నంబి ఆండార్ నంబి", "d": "Tamil Śaiva scholar who, by tradition, gathered the hymns of the Nāyaṉmārs into the Tirumuṟai at the wish of a Cōḷa king named Rājarāja.", "dt": "తమిళ శైవ పండితుడు; ఒక రాజరాజ చోళ రాజు కోరికపై నాయనార్ల పదికాలను తిరుమురైగా సేకరించాడని సంప్రదాయం." }
}, window.RMY_WHO || {});
